import { useQuery } from '@tanstack/react-query'
import { api } from '@/lib/api'
import { Puzzle, Download, Trash2 } from 'lucide-react'
import { useState } from 'react'

export function Skills() {
  const { data: skills, refetch } = useQuery({ queryKey: ['skills'], queryFn: api.getSkills })
  const [installSource, setInstallSource] = useState('')
  const [installing, setInstalling] = useState(false)

  const handleInstall = async () => {
    if (!installSource.trim()) return
    setInstalling(true)
    try {
      await api.installSkill(installSource.trim())
      setInstallSource('')
      refetch()
    } catch (e) {
      alert('安装失败: ' + (e as Error).message)
    } finally {
      setInstalling(false)
    }
  }

  const handleDelete = async (name: string) => {
    if (!confirm(`确定卸载技能 "${name}"？`)) return
    await api.deleteSkill(name)
    refetch()
  }

  return (
    <div className="p-6 space-y-6">
      <div>
        <h2 className="text-2xl font-bold">技能管理</h2>
        <p className="text-muted-foreground">管理已安装的技能包（Skill Packages）</p>
      </div>

      {/* Install */}
      <div className="flex gap-2">
        <input
          value={installSource}
          onChange={(e) => setInstallSource(e.target.value)}
          placeholder="输入技能路径、URL 或 Git 仓库地址"
          className="flex-1 rounded-lg border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
        />
        <button
          onClick={handleInstall}
          disabled={installing || !installSource.trim()}
          className="flex items-center gap-2 rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground hover:bg-primary/90 disabled:opacity-50"
        >
          <Download className="h-4 w-4" /> {installing ? '安装中...' : '安装'}
        </button>
      </div>

      {/* Skills list */}
      <div className="grid gap-3">
        {!skills || skills.length === 0 ? (
          <div className="rounded-xl border bg-card p-8 text-center">
            <Puzzle className="mx-auto h-10 w-10 text-muted-foreground mb-3" />
            <p className="text-muted-foreground">暂无已安装技能</p>
          </div>
        ) : (
          skills.map((skill) => (
            <div key={skill.name} className="rounded-xl border bg-card p-4">
              <div className="flex items-start gap-3">
                <Puzzle className="h-5 w-5 text-blue-500 mt-0.5" />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <h3 className="font-medium">{skill.name}</h3>
                    <span className="rounded bg-secondary px-1.5 py-0.5 text-xs text-secondary-foreground">
                      v{skill.version}
                    </span>
                    <span className="rounded bg-primary/10 px-1.5 py-0.5 text-xs text-primary">
                      {skill.source}
                    </span>
                  </div>
                  <p className="mt-1 text-sm text-muted-foreground">{skill.description}</p>
                  {skill.intents.length > 0 && (
                    <div className="mt-2 flex gap-1 flex-wrap">
                      {skill.intents.map((intent) => (
                        <span key={intent} className="rounded bg-muted px-2 py-0.5 text-xs">
                          {intent}
                        </span>
                      ))}
                    </div>
                  )}
                </div>
                {skill.source !== 'builtin' && (
                  <button
                    onClick={() => handleDelete(skill.name)}
                    className="rounded-lg p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4" />
                  </button>
                )}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  )
}
